/*
# DEMO DATA — for testing only (not a migration; run it manually)

Paste this whole file into Supabase → SQL Editor → Run.

What it adds
  1. 19 approved demo products across all categories (one is out of stock,
     to test the "Sold out" state). Images are small built-in illustrations,
     so nothing external is needed.
  2. Delivery zones for a few areas (only if that Zilla+Thana is not already
     there). The charges are PLACEHOLDERS — edit them in Admin Panel → Delivery Zones.
  3. Optional: 3 sample reels using public sample videos (see section 3).

The products are attached to the first seller account (or the admin if there is
no seller yet), so sign up / create the account first.

Safe to run more than once (products with the same name are skipped).

To remove all demo products later (only works for products nobody has ordered):
  DELETE FROM products WHERE description LIKE 'Demo product%';
*/

DO $$
DECLARE
  v_seller uuid;
BEGIN
  SELECT id INTO v_seller FROM profiles WHERE role = 'seller' ORDER BY created_at LIMIT 1;
  IF v_seller IS NULL THEN
    SELECT id INTO v_seller FROM profiles WHERE role = 'admin' ORDER BY created_at LIMIT 1;
  END IF;
  IF v_seller IS NULL THEN
    RAISE EXCEPTION 'No seller or admin account exists yet. Sign up on the site first, then run this again.';
  END IF;

  -- The approval guard trigger would force new rows to "pending"; switch it off just for this insert.
  ALTER TABLE products DISABLE TRIGGER trg_products_seller_guard;

  INSERT INTO products (seller_id, name, category, price, stock, unit, description, image_url, status, is_active)
  SELECT v_seller, d.name, d.category, d.price, d.stock, d.unit, d.description, d.image_url, 'approved', true
  FROM (VALUES
    ('Wireless Bluetooth Earbuds', 'Electronics', 1450, 25, 'pcs', 'Demo product — Compact true-wireless earbuds with a charging case and clear sound.', 'data:image/svg+xml;base64,'),
    ('20000mAh Power Bank', 'Electronics', 1850, 18, 'pcs', 'Demo product — High-capacity power bank with fast charging and dual USB output.', 'data:image/svg+xml;base64,'),
    ('Smart Watch Series X', 'Electronics', 3290, 10, 'pcs', 'Demo product — Fitness tracking, notifications and a bright touch display.', 'data:image/svg+xml;base64,'),
    ('Men''s Cotton Polo Shirt', 'Clothing', 690, 40, 'pcs', 'Demo product — Soft breathable cotton polo, comfortable for everyday wear.', 'data:image/svg+xml;base64,'),
    ('Women''s Printed Kurti', 'Clothing', 1150, 30, 'pcs', 'Demo product — Lightweight printed kurti with a relaxed, elegant fit.', 'data:image/svg+xml;base64,'),
    ('Leather Wallet', 'Clothing', 550, 0, 'pcs', 'Demo product — Slim genuine-leather wallet. (Out of stock — for testing the sold-out state.)', 'data:image/svg+xml;base64,'),
    ('Wooden Study Table', 'Furniture', 6200, 6, 'pcs', 'Demo product — Sturdy wooden study table with a smooth finish and a wide top.', 'data:image/svg+xml;base64,'),
    ('Yoga Mat 6mm', 'Sports', 780, 22, 'pcs', 'Demo product — Non-slip 6mm yoga mat, easy to roll and carry.', 'data:image/svg+xml;base64,'),
    ('Cricket Bat (Kashmir Willow)', 'Sports', 2450, 9, 'pcs', 'Demo product — Balanced Kashmir willow bat with a comfortable grip.', 'data:image/svg+xml;base64,'),
    ('Kids Building Blocks 120pc', 'Toys', 850, 35, 'set', 'Demo product — Colourful 120-piece block set that builds creativity.', 'data:image/svg+xml;base64,'),
    ('Baby Feeding Bottle Set', 'Baby Products', 620, 28, 'set', 'Demo product — BPA-free feeding bottle set with soft silicone nipples.', 'data:image/svg+xml;base64,'),
    ('Bangla Story Collection', 'Books', 380, 50, 'pcs', 'Demo product — A collection of classic short stories for all ages.', 'data:image/svg+xml;base64,'),
    ('Car Dashboard Phone Holder', 'Auto Accessories', 420, 45, 'pcs', 'Demo product — Adjustable dashboard phone holder with a strong grip.', 'data:image/svg+xml;base64,'),
    ('Pure Sundarban Honey 500g', 'Food & Beverages', 750, 60, 'jar', 'Demo product — Natural honey in a 500g jar, no added sugar.', 'data:image/svg+xml;base64,'),
    ('Premium Tea Leaf 500g', 'Food & Beverages', 420, 55, 'pack', 'Demo product — Fresh, aromatic tea leaf in a 500g pack.', 'data:image/svg+xml;base64,'),
    ('Gold-plated Necklace Set', 'Jewelry', 1890, 12, 'set', 'Demo product — Elegant gold-plated necklace and earring set.', 'data:image/svg+xml;base64,'),
    ('Vitamin C Face Serum 30ml', 'Cosmetics', 980, 30, 'pcs', 'Demo product — Brightening vitamin C serum, 30ml dropper bottle.', 'data:image/svg+xml;base64,'),
    ('Cordless Screwdriver Set', 'Hardware, Sanitary & Utilities', 1350, 16, 'set', 'Demo product — Rechargeable cordless screwdriver with assorted bits.', 'data:image/svg+xml;base64,'),
    ('Multi-purpose Toolkit Box', 'All-in-One Equipment Hub', 2150, 8, 'set', 'Demo product — Complete household toolkit in a sturdy carry box.', 'data:image/svg+xml;base64,')
  ) AS d(name, category, price, stock, unit, description, image_url)
  WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.name = d.name AND p.seller_id = v_seller);

  ALTER TABLE products ENABLE TRIGGER trg_products_seller_guard;
END $$;

-- ---------------------------------------------------------------
-- 2. Delivery zones (placeholder charges — edit in the Admin Panel)
-- ---------------------------------------------------------------
INSERT INTO delivery_zones (zilla, thana, delivery_charge) VALUES
  ('Jashore', 'Jashore Sadar', 60),
  ('Jashore', 'Manirampur', 60),
  ('Jashore', 'Keshabpur', 70),
  ('Jashore', 'Abhaynagar', 70),
  ('Khulna', 'Khulna Sadar', 80),
  ('Dhaka', 'Dhanmondi', 120),
  ('Dhaka', 'Mirpur', 120),
  ('Chattogram', 'Kotwali', 130)
ON CONFLICT (zilla, thana) DO NOTHING;

-- ---------------------------------------------------------------
-- 3. OPTIONAL sample reels (public sample videos; they need internet
--    access to the sample hosts. Real reels: upload from Seller Dashboard → Reels.)
--    Delete these lines if you don't want sample reels.
-- ---------------------------------------------------------------
INSERT INTO reels (seller_id, product_id, video_url, caption)
SELECT p.seller_id, p.id, v.url, v.caption
FROM (VALUES
  ('Wireless Bluetooth Earbuds', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', 'Sound that moves with you 🎧'),
  ('Pure Sundarban Honey 500g', 'https://www.w3schools.com/html/mov_bbb.mp4', 'Natural honey, straight from the source 🍯'),
  ('Smart Watch Series X', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', 'Track every step ⌚')
) AS v(product_name, url, caption)
JOIN products p ON p.name = v.product_name AND p.description LIKE 'Demo product%'
WHERE NOT EXISTS (SELECT 1 FROM reels r WHERE r.product_id = p.id AND r.video_url = v.url);
